# =============================================================================
# rollback.ps1 -- A04R 安全脚本构建包交付物
#
# 批准动作集（EV-001 / EV-002 / EV-003 / EV-005 / PR-001）全部为只读或
# Windows 工作区动作，设备侧零改动；因此回滚 = 清理执行工作区生成物
# （evidence / snapshot / ledger / journal / rollback 副本），即 PR-001
# 批准的"删除生成的脚本/台账文件即可（可逆）"。
#
# 本脚本不包含任何设备命令。默认 DryRun；加 -Execute 执行清理。
#
# fail-closed 守卫：
#   1) 目标必须是 <OutRoot>/HONOR_STAGE2_* 子目录（解析后校验绝对路径）；
#   2) 若台账含 WRITE 类别行（未来写波遗留的记录），拒绝清理并退出 3，
#      交由人工/上游裁定设备侧恢复方案。
#
# 退出码：0=成功（含"无内容可清理"）；1=参数/环境/路径错误；3=台账守卫拦截。
# =============================================================================

[CmdletBinding()]
param(
    [switch]$Execute,
    [string]$OutRoot = '',
    [string]$WorkspaceName = ''
)

$ErrorActionPreference = 'Stop'
$script:ScriptRoot = if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).Path }
if (-not $OutRoot) { $OutRoot = Join-Path $script:ScriptRoot 'outputs' }

try {
    $OutRootFull = [System.IO.Path]::GetFullPath($OutRoot)
    if (-not (Test-Path -LiteralPath $OutRootFull -PathType Container)) {
        Write-Host ('ROLLBACK: output root not found: ' + $OutRootFull)
        Write-Host 'ROLLBACK: nothing to clean (exit 0)'
        exit 0
    }

    $dirs = @(Get-ChildItem -LiteralPath $OutRootFull -Directory | Where-Object { $_.Name -like 'HONOR_STAGE2_*' })
    $target = $null
    if ($WorkspaceName) {
        $target = $dirs | Where-Object { $_.Name -eq $WorkspaceName } | Select-Object -First 1
        if (-not $target) {
            Write-Host ('ROLLBACK: workspace not found: ' + $WorkspaceName)
            Write-Host 'ROLLBACK: nothing to clean (exit 0)'
            exit 0
        }
    } else {
        $target = $dirs | Sort-Object LastWriteTime -Descending | Select-Object -First 1
        if (-not $target) {
            Write-Host 'ROLLBACK: no HONOR_STAGE2_* workspace found under output root'
            Write-Host 'ROLLBACK: nothing to clean (exit 0)'
            exit 0
        }
    }

    $targetFull = [System.IO.Path]::GetFullPath($target.FullName)
    $sep = [System.IO.Path]::DirectorySeparatorChar
    $rootPrefix = $OutRootFull.TrimEnd($sep) + $sep
    if (-not $targetFull.StartsWith($rootPrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw ('ROLLBACK: target outside out root; refusing: ' + $targetFull)
    }
    if ($targetFull -eq $OutRootFull) {
        throw 'ROLLBACK: target equals out root; refusing'
    }

    $ledgerPath = Join-Path $targetFull 'ledger\state_ledger.tsv'
    if (Test-Path -LiteralPath $ledgerPath) {
        $writeRows = @(Get-Content -LiteralPath $ledgerPath | Select-Object -Skip 1 | Where-Object { $_ -match '^WRITE' })
        if ($writeRows.Count -gt 0) {
            Write-Host ('ROLLBACK: ledger contains ' + $writeRows.Count + ' WRITE-category row(s); device-side restore is outside the approved read-only scope; manual adjudication required. Refusing workspace cleanup.')
            exit 3
        }
    }

    if ($Execute) {
        Write-Host ('ROLLBACK: removing ' + $targetFull)
        Remove-Item -LiteralPath $targetFull -Recurse -Force
        Write-Host 'ROLLBACK: done (exit 0)'
    } else {
        Write-Host ('ROLLBACK DRYRUN: would remove ' + $targetFull)
        Write-Host 'ROLLBACK DRYRUN: nothing removed. Re-run with -Execute to clean.'
    }
    exit 0
} catch {
    Write-Host ('ROLLBACK ERROR: ' + $_.Exception.Message)
    exit 1
}

